def _file_sha256(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda:f.read(1024*1024),b''): h.update(block)
    return h.hexdigest()

class CivStateReader:
    """Strict read-only adapter for the locked adjacent civilization database."""
    def __init__(self,path):
        self.path=Path(path).resolve()
        if not self.path.is_file(): raise RuntimeError(f'locked CIVSTATE database not found: {self.path}')
        self.sha256=_file_sha256(self.path)
        if self.sha256!=CIVSTATE_SHA256:
            raise RuntimeError(f'CIVSTATE lock hash mismatch: expected {CIVSTATE_SHA256}, received {self.sha256}')
        self.db=sqlite3.connect(f'file:{self.path.as_posix()}?mode=ro',uri=True)
        self.db.row_factory=sqlite3.Row
        self.db.execute('PRAGMA query_only=ON')
        meta=dict(self.db.execute('SELECT key,value FROM civ_meta'))
        if meta.get('schema_name')!=CIVSTATE_SCHEMA: raise RuntimeError('CIVSTATE schema_name mismatch')
        if meta.get('schema_version')!=CIVSTATE_VERSION: raise RuntimeError('CIVSTATE schema_version mismatch')
        if self.db.execute('PRAGMA quick_check').fetchone()[0]!='ok': raise RuntimeError('CIVSTATE quick_check failed')
        required={'civ_subject','civ_infrastructure_state','civ_transport_flow','civ_runtime_place_context'}
        found={r[0] for r in self.db.execute("SELECT name FROM sqlite_master WHERE type IN ('table','view')")}
        missing=sorted(required-found)
        if missing: raise RuntimeError('CIVSTATE runtime objects missing: '+', '.join(missing))
        self.meta=meta
        self._validate_tokens()
    def _validate_tokens(self):
        for token,eid in CIVSTATE_TOKEN_ENTITY.items():
            row=self.db.execute(
                "SELECT subject_id FROM civ_subject WHERE subject_id=? AND navigator_entity_id=? AND aggregation_class='NAVIGATOR_ENTITY'",
                (f'ENTITY:{eid}',eid)).fetchone()
            if row is None: raise RuntimeError(f'CIVSTATE has no spatial binding for navigation token {token}')
    def _entity_subject(self,token):
        token=_resolve_dest(token)
        return 'ENTITY:'+CIVSTATE_TOKEN_ENTITY[token]
    def place_context(self,token):
        root=self._entity_subject(token)
        q="""
        WITH RECURSIVE spatial(subject_id) AS (
          SELECT ?
          UNION ALL
          SELECT s.subject_id FROM civ_subject s JOIN spatial p ON s.parent_subject_id=p.subject_id
          WHERE s.aggregation_class='NAVIGATOR_ENTITY'
        ), node_ids(subject_id) AS (
          SELECT n.subject_id FROM civ_subject n JOIN spatial p ON n.spatial_subject_id=p.subject_id
          WHERE n.aggregation_class='INFRASTRUCTURE'
        )
        SELECT COUNT(*) AS facilities,
               COALESCE(SUM(resident_population),0) AS resident_population,
               COALESCE(SUM(transient_daily_population),0) AS transient_daily_population,
               COALESCE(SUM(workforce),0) AS workforce,
               COALESCE(SUM(annual_value_added),0) AS annual_value_added,
               COALESCE(SUM(power_average_mw),0) AS power_average_mw,
               COALESCE(SUM(cargo_throughput_tonnes_year),0) AS cargo_throughput_tonnes_year,
               COALESCE(MAX(strategic_importance),0) AS strategic_importance
        FROM civ_runtime_place_context c JOIN node_ids n ON n.subject_id=c.subject_id
        """
        out=dict(self.db.execute(q,(root,)).fetchone())
        top=self.db.execute("""
        WITH RECURSIVE spatial(subject_id) AS (
          SELECT ? UNION ALL SELECT s.subject_id FROM civ_subject s JOIN spatial p ON s.parent_subject_id=p.subject_id
          WHERE s.aggregation_class='NAVIGATOR_ENTITY'
        )
        SELECT c.subject_id,c.display_name,c.governance_style,c.local_civil_authority,
               c.security_provider,c.strategic_importance,c.transport_centrality
        FROM civ_runtime_place_context c JOIN civ_subject n ON n.subject_id=c.subject_id
        JOIN spatial p ON n.spatial_subject_id=p.subject_id
        ORDER BY COALESCE(c.strategic_importance,0) DESC,COALESCE(c.transport_centrality,0) DESC,c.subject_id LIMIT 3
        """,(root,)).fetchall()
        out.update({'token':_resolve_dest(token),'root_subject_id':root,'top_facilities':[dict(r) for r in top],
                    'civstate_sha256':self.sha256,'year':2226})
        return out
    def route_context(self,origin,destination):
        o=self._entity_subject(origin); d=self._entity_subject(destination)
        q="""
        WITH RECURSIVE os(subject_id) AS (
          SELECT ? UNION ALL SELECT s.subject_id FROM civ_subject s JOIN os p ON s.parent_subject_id=p.subject_id
          WHERE s.aggregation_class='NAVIGATOR_ENTITY'
        ), ds(subject_id) AS (
          SELECT ? UNION ALL SELECT s.subject_id FROM civ_subject s JOIN ds p ON s.parent_subject_id=p.subject_id
          WHERE s.aggregation_class='NAVIGATOR_ENTITY'
        ), onodes(subject_id) AS (
          SELECT n.subject_id FROM civ_subject n JOIN os p ON n.spatial_subject_id=p.subject_id WHERE n.aggregation_class='INFRASTRUCTURE'
        ), dnodes(subject_id) AS (
          SELECT n.subject_id FROM civ_subject n JOIN ds p ON n.spatial_subject_id=p.subject_id WHERE n.aggregation_class='INFRASTRUCTURE'
        )
        SELECT COUNT(*) AS flow_records,COALESCE(SUM(passengers_year),0) AS passengers_year,
               COALESCE(SUM(freight_tonnes_year),0) AS freight_tonnes_year,
               COALESCE(SUM(ship_movements),0) AS ship_movements,
               COALESCE(MAX(route_importance),0) AS route_importance
        FROM civ_transport_flow f JOIN onodes a ON a.subject_id=f.origin_subject_id
        JOIN dnodes b ON b.subject_id=f.destination_subject_id WHERE f.year=2226
        """
        out=dict(self.db.execute(q,(o,d)).fetchone())
        out.update({'origin':_resolve_dest(origin),'destination':_resolve_dest(destination),
                    'civstate_sha256':self.sha256,'year':2226})
        return out
    def verify(self):
        return {'status':'PASS','path':str(self.path),'sha256':self.sha256,
                'schema_name':self.meta['schema_name'],'schema_version':self.meta['schema_version'],
                'runtime_role':self.meta.get('runtime_role'),'tokens':len(CIVSTATE_TOKEN_ENTITY)}

def _civstate_path(root):
    explicit=os.environ.get('LOOM_CIVSTATE_DB','').strip()
    if explicit:
        return Path(explicit)
    data_dir=os.environ.get('LOOM_DATA_DIR','').strip()
    if data_dir:
        candidate=Path(data_dir)/CIVSTATE_FILE
        if candidate.is_file(): return candidate
    # Solar GIS keeps all three LOOM databases here on Android.  Navigator's
    # campaign state and physics packages remain in Download; only CIVSTATE is
    # resolved from the shared data directory.
    if CIVSTATE_ANDROID_PATH.is_file():
        return CIVSTATE_ANDROID_PATH
    return Path(root)/CIVSTATE_FILE

def _civstate_for_root(root):
    global _CIVSTATE_ACTIVE
    wanted=_civstate_path(root).resolve()
    if _CIVSTATE_ACTIVE is None or _CIVSTATE_ACTIVE.path!=wanted:
        _CIVSTATE_ACTIVE=CivStateReader(wanted)
    return _CIVSTATE_ACTIVE

