def _sha_bytes(b): return hashlib.sha256(b).hexdigest()
def _canon(x): return json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode('utf-8')
def _deepcopy(x): return json.loads(json.dumps(x,ensure_ascii=False))
def _slug(s):
    t=re.sub(r'[^A-Za-z0-9]+','-',str(s).strip()).strip('-').upper()
    return t[:24] or 'UNNAMED'

def _state_payload(s): return {k:v for k,v in s.items() if k not in ('state_id','state_sha256')}
def _stamp_state(s,revision):
    s=_deepcopy(s); s['revision']=int(revision)
    h=_sha_bytes(_canon(_state_payload(s)))
    s['state_sha256']=h; s['state_id']=f"S{revision:06d}-{h[:12]}"
    return s

def _validate_state(s):
    if s.get('schema')!=STATE_SCHEMA: raise RuntimeError('save schema mismatch')
    expect=_sha_bytes(_canon(_state_payload(s)))
    if s.get('state_sha256')!=expect: raise RuntimeError('save state hash mismatch')
    if s.get('state_id')!=f"S{int(s['revision']):06d}-{expect[:12]}": raise RuntimeError('save state ID mismatch')
    sh=s['ship']
    if float(sh['remass_t']) < -1e-9: raise RuntimeError('negative remass')
    if float(sh['wet_mass_t']) <= 0: raise RuntimeError('non-positive wet mass')
    return s

def _atomic_save(path,bak,state):
    tmp=path.with_suffix(path.suffix+'.tmp')
    raw=(json.dumps(state,indent=2,ensure_ascii=False)+'\n').encode('utf-8')
    tmp.write_bytes(raw)
    _validate_state(json.loads(tmp.read_text(encoding='utf-8')))
    if path.exists(): shutil.copy2(path,bak)
    os.replace(tmp,path)
    return len(raw)

def _campaign_ids(campaign_name,ship_name):
    return 'C-'+uuid.uuid4().hex[:12].upper(), 'SHIP-'+uuid.uuid4().hex[:12].upper()

def _new_state(campaign_name,ship_name,ship_class='WAYFARER'):
    if ship_class.strip().upper() not in ('WAYFARER','WAYFARER_BASELINE'):
        raise RuntimeError('Sequence H MVP currently supports WAYFARER only')
    cid,sid=_campaign_ids(campaign_name,ship_name)
    fixed_nonremass=1158.5-250.0
    config={'ship_baseline':'WAYFARER_BASELINE','installed':['WAYFARER_BASELINE'],'model_status':'CANON_BASELINE'}
    s={
      'schema':STATE_SCHEMA,'sequence_h_version':SEQUENCE_H_VERSION,
      'campaign':{'campaign_id':cid,'campaign_name':campaign_name},
      'ship_identity':{'ship_instance_id':sid,'ship_name':ship_name,'ship_class':'WAYFARER','ship_template':'WAYFARER_BASELINE'},
      'epoch_utc':'2027-06-15T02:00:00Z','display_timezone':'Australia/Melbourne',
      'location_token':'CERES','status':'READY_HOLD',
      'ship':{
        'baseline':'WAYFARER_BASELINE','fixed_nonremass_mass_t':fixed_nonremass,'variable_cargo_t':0.0,
        'remass_capacity_t':250.0,'remass_t':250.0,'wet_mass_t':1158.5,
        'fusion_fuel':{'status':'OPEN_MODEL','quantity_t':None},
        'thermal':{'status':'OPEN_MODEL','last_declared_action':'NONE'},
        'configuration':config,'configuration_sha256':_sha_bytes(_canon(config)),
        'condition':{'status':'PLACEHOLDER_NO_DAMAGE_MODEL','ship_destroyed':False}
      },
      'kinematic_boundary':{'status':'BODY_RENDEZVOUS','source':'initial campaign fixture','state_source_units':None},
      'last_flight':None,'last_reconciliation':None,
      'authority':{'llm_simulation_state_authority':'ZERO','llm_calculation_authority':'ZERO','python':'AUTHORITATIVE'}
    }
    return _stamp_state(s,1)

def _migrate_prototype_state(old,campaign_name,ship_name):
    _validate_state(old)
    cid,sid=_campaign_ids(campaign_name,ship_name)
    ns=_deepcopy(old)
    ns['sequence_h_version']=SEQUENCE_H_VERSION
    ns['campaign']={'campaign_id':cid,'campaign_name':campaign_name}
    ns['ship_identity']={'ship_instance_id':sid,'ship_name':ship_name,'ship_class':'WAYFARER','ship_template':'WAYFARER_BASELINE'}
    ns['ship'].setdefault('condition',{'status':'PLACEHOLDER_NO_DAMAGE_MODEL','ship_destroyed':False})
    ns['ship']['condition'].setdefault('ship_destroyed',False)
    return _stamp_state(ns,int(old['revision'])+1)

def _identity(state):
    return {
      'campaign_id':state['campaign']['campaign_id'],'campaign_name':state['campaign']['campaign_name'],
      'ship_instance_id':state['ship_identity']['ship_instance_id'],'ship_name':state['ship_identity']['ship_name'],
      'ship_class':state['ship_identity']['ship_class']
    }

def _record_hash_payload(rec): return {k:v for k,v in rec.items() if k!='record_sha256'}

def _archive_paths(root):
    return sorted(root.glob('LOOM_CAMPAIGN_HISTORY_ARCHIVE_*.jsonl.gz'))

def _read_gzip_jsonl(path):
    if not path.exists(): return []
    out=[]
    with gzip.open(path,'rt',encoding='utf-8') as f:
        for ln,line in enumerate(f,1):
            if not line.strip(): continue
            try: out.append(json.loads(line))
            except Exception as e: raise RuntimeError(f'corrupt history JSON {path.name}:{ln}: {e}')
    return out


def _history_backup_path(path):
    path=Path(path)
    return path.with_name(path.name+'.bak')

def _history_corrupt_path(path):
    path=Path(path)
    return path.with_name(path.name+'.corrupt')

def _write_gzip_jsonl_atomic(path, records):
    """
    Write the complete ACTIVE history to a temp sibling, verify it, fsync,
    preserve the previous readable live history as .bak, then atomically replace.
    """
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_name(path.name+'.tmp')
    bak=_history_backup_path(path)

    with open(tmp,'wb') as raw:
        with gzip.GzipFile(fileobj=raw,mode='wb',compresslevel=9,mtime=0) as gz:
            for r in records:
                gz.write((json.dumps(r,separators=(',',':'),ensure_ascii=False)+'\n').encode('utf-8'))
        raw.flush(); os.fsync(raw.fileno())

    chk=_read_gzip_jsonl(tmp)
    if len(chk)!=len(records):
        raise RuntimeError('history temp verification record-count mismatch')

    if path.exists():
        try:
            _read_gzip_jsonl(path)
            shutil.copy2(path,bak)
        except Exception:
            pass

    os.replace(tmp,path)
    try:
        dfd=os.open(str(path.parent),os.O_RDONLY)
        try: os.fsync(dfd)
        finally: os.close(dfd)
    except Exception:
        pass

def _read_active_history_with_backup_recovery(path):
    """
    Explicit conservative startup recovery for a torn/corrupt active history.
    A fully readable .bak is required. The corrupt primary is preserved as
    .corrupt before the backup is restored.
    """
    path=Path(path)
    if not path.exists():
        return [],'NO_HISTORY'
    try:
        return _read_gzip_jsonl(path),'PRIMARY_OK'
    except Exception as primary_error:
        bak=_history_backup_path(path)
        if not bak.exists():
            raise RuntimeError(
                f'active campaign history unreadable and no backup exists: {primary_error!r}'
            )
        try:
            recs=_read_gzip_jsonl(bak)
        except Exception as backup_error:
            raise RuntimeError(
                f'active campaign history and backup unreadable: primary={primary_error!r}; backup={backup_error!r}'
            )
        corrupt=_history_corrupt_path(path)
        try:
            if corrupt.exists(): corrupt.unlink()
            os.replace(path,corrupt)
        except Exception:
            pass
        shutil.copy2(bak,path)
        return recs,'RECOVERED_FROM_BACKUP'

class HistoryLedger:
    def __init__(self,root,state,max_records=HISTORY_MAX,warn_records=HISTORY_WARN):
        self.root=Path(root); self.path=self.root/HISTORY_FILE; self.state=state
        self.max_records=max_records; self.warn_records=warn_records
        self.records=[]; self.active_count=0; self.last_sha=None; self.next_number=1
        self._load_verify()
    def _load_verify(self):
        recs=[]
        for p in _archive_paths(self.root): recs.extend(_read_gzip_jsonl(p))
        active,self.history_recovery_status=_read_active_history_with_backup_recovery(self.path)
        self.active_count=len(active); recs.extend(active)
        prev=None; expected_num=1
        for r in recs:
            if r.get('schema')!=HISTORY_SCHEMA: raise RuntimeError('history schema mismatch')
            if int(r.get('record_number',-1))!=expected_num: raise RuntimeError('history record numbering gap')
            if r.get('previous_record_sha256')!=prev: raise RuntimeError('history hash-chain previous mismatch')
            want=_sha_bytes(_canon(_record_hash_payload(r)))
            if r.get('record_sha256')!=want: raise RuntimeError('history record hash mismatch')
            prev=want; expected_num+=1
        self.records=recs; self.last_sha=prev; self.next_number=expected_num
    def verify(self):
        self._load_verify(); return {'status':'PASS','records':len(self.records),'active_records':self.active_count,'last_sha256':self.last_sha}
    def latest_state_snapshot(self):
        for r in reversed(self.records):
            s=r.get('state_after_snapshot')
            if s is not None: return r,s
        return None,None
    def _next_archive_path(self):
        nums=[]
        for p in _archive_paths(self.root):
            m=re.search(r'ARCHIVE_(\d+)\.jsonl\.gz$',p.name)
            if m: nums.append(int(m.group(1)))
        n=(max(nums)+1) if nums else 1
        return self.root/f'LOOM_CAMPAIGN_HISTORY_ARCHIVE_{n:03d}.jsonl.gz'
    def archive_now(self):
        if not self.path.exists() or self.active_count==0: return None
        dest=self._next_archive_path(); os.replace(self.path,dest); self.active_count=0
        # Keep global chain continuity; append() will use current last_sha / next_number.
        self.append('HISTORY_ARCHIVE_CONTINUATION',self.state,self.state,{
          'archive_file':dest.name,'archive_record_count':len(_read_gzip_jsonl(dest))
        },allow_archive=False)
        return dest
    def ensure_capacity(self):
        if self.active_count>=self.max_records:
            print(f'\nHISTORY LIMIT {self.active_count}/{self.max_records}. Archive required before continuing.')
            if input('ARCHIVE ACTIVE HISTORY NOW? [y/N] ').strip().lower()!='y':
                raise RuntimeError('history maximum reached; no records discarded')
            dest=self.archive_now(); print('HISTORY ARCHIVED       ',dest)
        elif self.active_count>=self.warn_records:
            print(f'\nHISTORY WARNING         {self.active_count}/{self.max_records} active records')
    def append(self,record_type,state_before,state_after,details=None,flight_id=None,event_epoch_utc=None,state_after_snapshot=None,allow_archive=True):
        if record_type not in RESERVED_HISTORY_EVENTS: raise RuntimeError(f'unregistered history event {record_type}')
        if allow_archive: self.ensure_capacity()
        ident=_identity(state_after or state_before or self.state)
        rec={
          'schema':HISTORY_SCHEMA,'record_number':self.next_number,'record_type':record_type,
          **ident,'event_epoch_utc':event_epoch_utc or (state_after or state_before)['epoch_utc'],
          'previous_record_sha256':self.last_sha,
          'state_before_sha256':state_before.get('state_sha256') if state_before else None,
          'state_after_sha256':state_after.get('state_sha256') if state_after else None,
          'flight_id':flight_id,'details':details or {},'state_after_snapshot':state_after_snapshot
        }
        rec['record_sha256']=_sha_bytes(_canon(_record_hash_payload(rec)))
        active=_read_gzip_jsonl(self.path) if self.path.exists() else []
        prospective=active+[rec]
        _write_gzip_jsonl_atomic(self.path,prospective)
        self.records.append(rec); self.active_count+=1; self.last_sha=rec['record_sha256']; self.next_number+=1
        return rec
    def recent_flights(self,n=20):
        done=[r for r in self.records if r['record_type'] in ('FLIGHT_ARRIVED','FLIGHT_ABORTED','SHIP_DESTROYED')]
        return done[-n:]
    def flight_records(self,fid): return [r for r in self.records if r.get('flight_id')==fid]
    def next_flight_id(self):
        mx=0
        for r in self.records:
            m=re.fullmatch(r'F(\d+)',str(r.get('flight_id') or ''))
            if m: mx=max(mx,int(m.group(1)))
        return f'F{mx+1:06d}'

def _history_recover_if_needed(ledger,state,state_path,bak_path):
    rec,snap=ledger.latest_state_snapshot()
    if snap is None: return state
    _validate_state(snap)
    if snap['state_sha256']==state['state_sha256']: return state
    if int(snap['revision'])>int(state['revision']) and rec.get('state_before_sha256')==state['state_sha256']:
        print('\nRECOVERY               history has one fully committed state ahead of save')
        print('RECOVER TO             ',snap['state_id'])
        if input('RECOVER AUTHORITATIVE SAVE? [Y/n] ').strip().lower() not in ('n','no'):
            _atomic_save(state_path,bak_path,snap); ledger.state=snap; return snap
    raise RuntimeError('state/history divergence requires manual recovery; refusing to guess')

def _handoff(s):
    ident=_identity(s)
    vals=[HANDOFF_SCHEMA,
      f"CAMPAIGN={ident['campaign_name']}",f"CAMPAIGN_ID={ident['campaign_id']}",
      f"SHIP={ident['ship_name']}",f"SHIP_INSTANCE_ID={ident['ship_instance_id']}",
      f"STATE_ID={s['state_id']}",f"EPOCH_UTC={s['epoch_utc']}",f"LOCATION={s['location_token']}",f"STATUS={s['status']}",
      f"REMASS_T={s['ship']['remass_t']:.9f}",f"WET_MASS_T={s['ship']['wet_mass_t']:.9f}",
      f"CARGO_T={s['ship']['variable_cargo_t']:.9f}",f"THERMAL_STATUS={s['ship']['thermal']['status']}",
      f"CONFIG_SHA={s['ship']['configuration_sha256']}",f"LAST_FLIGHT={(s['last_flight'] or {}).get('flight_id','NONE')}",'END']
    return '\n'.join(vals)

def _print_state(s,ledger=None):
    i=_identity(s); print('\nAUTHORITATIVE CAMPAIGN STATE'); print('-'*78)
    print('CAMPAIGN               ',i['campaign_name'],'/',i['campaign_id'])
    print('SHIP                   ',i['ship_name'],'/',i['ship_instance_id'])
    print('STATE                  ',s['state_id']); print('EPOCH UTC              ',s['epoch_utc'])
    print('LOCATION               ',s['location_token']); print('STATUS                 ',s['status'])
    print('REMASS                 ',f"{s['ship']['remass_t']:.6f} t")
    print('WET MASS               ',f"{s['ship']['wet_mass_t']:.6f} t")
