def _outcome_summary(nav,runtime,det,html,state_before,arrival,flight_id,plan_sha):
    leg=runtime['flight']['legs'][-1]; b=leg['terminal_burn']; v0=leg['ordinary_velocity_memory']['acquisition_velocity_km_s']
