def _mvp_recent_activity(ledger,n=20):
    print('\\nRECENT CAMPAIGN ACTIVITY')
    shown=0
    for r in reversed(ledger.records):
        if r['record_type'] in ('JOB_ACCEPTED','JOB_CANCELLED','CARGO_LOADED','JOB_COMPLETED',
                                'REMASS_REFUELED','SERVICE_EVENT','CAMPAIGN_NOTE','CARGO_RECOVERY_UNLOAD',
                                'FLIGHT_ARRIVED','FLIGHT_ABORTED','SHIP_DESTROYED'):
            print(f"{r['record_number']:>6} {r['record_type']:<20} {r['event_epoch_utc']} {r.get('flight_id') or ''}")
            shown+=1
            if shown>=n: break
    if not shown: print('NONE')

