def _mvp_flight_interactive():
    global _MVP_INJECTED_COMMAND
    dl,sp,bp,s,ledger=_mvp_context()
    _,m=_mvp_runtime(s); j=m.get('active_job')
    if j:
        status=j.get('status')
        if status=='ACCEPTED':
            raise RuntimeError(
                f"active job {j.get('job_id')} cargo is not loaded; choose 2 LOAD ACTIVE JOB CARGO before flight"
            )
        if status=='LOADED':
            cargo=float(s['ship']['variable_cargo_t'])
            if cargo > MVP_CARGO_OPERATIONAL_CAP_T + 1e-9:
                raise RuntimeError(
                    f'current cargo {cargo:.3f} t exceeds MVP operational cap '
                    f'{MVP_CARGO_OPERATIONAL_CAP_T:.3f} t; use 13 RECOVER / UNLOAD ACTIVE JOB'
                )
            dest=j['destination']
            print('FLIGHT DESTINATION      ',dest,'[ACTIVE JOB / CARGO LOADED]')
        else:
            raise RuntimeError(f"active job has unsupported flight status {status}")
    else:
        dest=input('DESTINATION: ').strip()
    civ=_civstate_for_root(dl)
    route_civ=civ.route_context(s['location_token'],dest)
    print('CIVSTATE ROUTE FLOWS   ',int(route_civ['flow_records']))
    print('CIVSTATE FREIGHT/YEAR  ',f"{route_civ['freight_tonnes_year']:,.0f} t")
    priority=(input('PRIORITY [BALANCED]: ').strip() or 'BALANCED').upper()
    # MVP v1.0 intentionally keeps optional physics providers OFF. They may be
    # re-enabled later without blocking the ordinary courier loop.
    _MVP_INJECTED_COMMAND={
      'BASE_STATE':s['state_id'],'ELAPSED_HOURS':'0','LOCATION':s['location_token'],
      'DESTINATION':dest,'PRIORITY':priority,
      'CONSIDER_GRAVITY_ASSISTS':'NO','CONSIDER_PRECISION_COLLAPSE':'NO',
      'CONSIDER_SOLAR_WEATHER':'NO','CONSIDER_EXCHANGE_ASSIST':'NO',
      'NOTES':('MVP v1.0 courier flight generated by local workflow; '
               f"CIVSTATE 2226 {route_civ['civstate_sha256'][:12]} route records={int(route_civ['flow_records'])}.")
    }
    _navigator_one_action_main()

