def _mvp_parse_menu_choice(raw):
    choice=str(raw).strip().upper()
    cleaned=''.join(ch for ch in choice if ch.isprintable() and ch not in '\u200b\u200c\u200d\ufeff')
    m=re.match(r'^\s*(\d+|[A-Z]+)',cleaned)
    cmd=(m.group(1) if m else cleaned).upper()
    aliases={
      'JOB':'1','TAKE':'1','LOAD':'2','FLY':'3','PLAN':'3','COMPLETE':'4','UNLOAD':'4',
      'REFUEL':'5','SERVICE':'6','NOTE':'7','STATUS':'8','HANDOFF':'8','VERIFY':'9',
      'HISTORY':'10','RECENT':'10','CANCEL':'11','ARCHIVE':'12','RECOVER':'13','UNLOADRECOVERY':'13','EXIT':'0','QUIT':'0'
    }
    return aliases.get(cmd,cmd)

def _mvp_self_test():
    import tempfile
    td=Path(tempfile.mkdtemp(prefix='loom_mvp_'))
    s=_new_state('MVP TEST','TEST SHIP')
    _validate_state(s)
    ledger=HistoryLedger(td,s)
    ledger.append('CAMPAIGN_CREATED',None,s,{'test':True},state_after_snapshot=s)
    sp=td/'state.json'; bp=td/'state.bak'
    _atomic_save(sp,bp,s)

    # Accept -> load.
    a=_mvp_accept_job_state(s,'MERCURY',12.5,1000,'test cargo')
    ledger.append('JOB_ACCEPTED',s,a,{'test':True},state_after_snapshot=a); _atomic_save(sp,bp,a)
    assert a['mvp_runtime']['active_job']['status']=='ACCEPTED'
    b=_mvp_load_job_state(a)
    ledger.append('CARGO_LOADED',a,b,{'test':True},state_after_snapshot=b); _atomic_save(sp,bp,b)
    assert abs(b['ship']['variable_cargo_t']-12.5)<1e-9
    assert abs(b['ship']['wet_mass_t']-(b['ship']['fixed_nonremass_mass_t']+b['ship']['remass_t']+12.5))<1e-9

    # Time/service and refuel invariants.
    c=_mvp_advance_state(b,6.0,'service')
    ledger.append('SERVICE_EVENT',b,c,{'test':True},state_after_snapshot=c); _atomic_save(sp,bp,c)
    c['ship']['remass_t']=200.0; c=_mvp_stamp_from(c)
    d=_mvp_refuel_state(c,None)
    assert abs(d['ship']['remass_t']-d['ship']['remass_capacity_t'])<1e-9

    # Simulate qualified arrival solely to test job completion state plumbing.
    d['location_token']='MERCURY'; d=_mvp_stamp_from(d)
    e=_mvp_complete_job_state(d)
    ledger.append('JOB_COMPLETED',d,e,{'test':True},state_after_snapshot=e); _atomic_save(sp,bp,e)
    assert e['mvp_runtime']['active_job'] is None
    assert abs(e['ship']['variable_cargo_t'])<1e-9
    assert abs(e['mvp_runtime']['balance_cr']-1000.0)<1e-9

    # Duplicate / invalid guards.
    try: _mvp_load_job_state(e)
    except RuntimeError: pass
    else: raise AssertionError('load without job was accepted')
    try: _mvp_refuel_state(e,float(e['ship']['remass_capacity_t'])+1)
    except RuntimeError: pass
    else: raise AssertionError('over-capacity refuel was accepted')

    _validate_state(json.loads(sp.read_text()))
    assert ledger.verify()['status']=='PASS'
    print('MVP STATE TRANSACTIONS  PASS')
    print('MVP JOB LOOP            PASS')
    print('MVP MASS ACCOUNTING     PASS')
    print('MVP SAVE/RELOAD         PASS')
    print('MVP HISTORY CHAIN       PASS')
    assert _mvp_parse_menu_choice('1')=='1'
    assert _mvp_parse_menu_choice('\u200b1\ufeff')=='1'
    assert _mvp_parse_menu_choice('JOB')=='1'
    assert _mvp_parse_menu_choice('10')=='10'

    # A courier job may never be flown before cargo is loaded.
    accepted=_mvp_accept_job_state(e,'PLUTO_SYSTEM',5.0,50.0,'flight guard')
    try:
        # Mirror the production preflight state gate without invoking the
        # interactive planner.
        jj=accepted['mvp_runtime']['active_job']
        if jj and jj.get('status')=='ACCEPTED':
            raise RuntimeError('cargo not loaded')
    except RuntimeError:
        pass
    else:
        raise AssertionError('accepted-but-unloaded job passed flight gate')

    # Cargo admission cap at acceptance.
    try:
        _mvp_accept_job_state(e,'PLUTO_SYSTEM',MVP_CARGO_OPERATIONAL_CAP_T+1,100,'oversize')
    except RuntimeError:
        pass
    else:
        raise AssertionError('oversize cargo job was accepted')

    # Recovery of a legacy/qualification oversize loaded state is transactional.
    legacy=_deepcopy(e)
    legacy,mleg=_mvp_runtime(legacy)
    mleg['job_counter']=99
    mleg['active_job']={
      'job_id':'JOB000099','status':'LOADED','origin':legacy['location_token'],
      'destination':'PLUTO_SYSTEM','cargo_t':1000.0,'reward_cr':0.0,
      'description':'legacy oversize test','accepted_epoch_utc':legacy['epoch_utc'],
      'loaded_epoch_utc':legacy['epoch_utc'],'completed_epoch_utc':None
    }
    legacy['ship']['variable_cargo_t']=1000.0
    legacy=_mvp_stamp_from(legacy)
    recovered,recjob=_mvp_recover_loaded_job_state(legacy)
    assert recovered['mvp_runtime']['active_job'] is None
    assert abs(recovered['ship']['variable_cargo_t'])<1e-9
    assert recjob['status']=='CANCELLED_RECOVERY'

    print('MVP MENU PARSER         PASS')
    print('MVP PREFLIGHT JOB GUARD PASS')
    # Provisional reward sanity cap.
    try:
        _mvp_accept_job_state(e,'PLUTO_SYSTEM',1.0,MVP_REWARD_SANITY_CAP_CR+1,'absurd reward')
    except RuntimeError:
        pass
    else:
        raise AssertionError('absurd reward was accepted')

    # Crash test A: abandoned/torn temp cannot damage the live history.
    htd=Path(tempfile.mkdtemp(prefix='loom_hist_atomic_'))
    hp=htd/'LOOM_CAMPAIGN_HISTORY.jsonl.gz'
    seed=[{'x':1}]
    _write_gzip_jsonl_atomic(hp,seed)
    live_before=hp.read_bytes()
    tmp=hp.with_name(hp.name+'.tmp')
    tmp.write_bytes(live_before[:max(1,len(live_before)//2)])
    assert hp.read_bytes()==live_before
    assert _read_gzip_jsonl(hp)==seed

    # Crash test B: completed history replacement remains readable and backup exists.
    prospective=[{'x':1},{'x':2}]
    _write_gzip_jsonl_atomic(hp,prospective)
    assert _read_gzip_jsonl(hp)==prospective
    assert _history_backup_path(hp).exists()

    # Crash test C: torn primary + good backup -> explicit backup recovery.
    shutil.copy2(hp,_history_backup_path(hp))
    raw=hp.read_bytes()
    hp.write_bytes(raw[:-5])
    recovered,status=_read_active_history_with_backup_recovery(hp)
    assert status=='RECOVERED_FROM_BACKUP'
    assert recovered==prospective
    assert _read_gzip_jsonl(hp)==prospective
    assert _history_corrupt_path(hp).exists()

    print('MVP CARGO CAP GATE      PASS')
    print('MVP RECOVERY UNLOAD     PASS')
    print('MVP REWARD SANITY CAP   PASS')
    print('MVP HISTORY ATOMIC WRITE PASS')
    print('MVP HISTORY BACKUP RECOVERY PASS')
    print('MVP INVALID-GUARDS      PASS')

def _mvp_main():
    # Ensure/migrate campaign first.
    dl,sp,bp,s,ledger=_mvp_context()
    while True:
        dl,sp,bp,s,ledger=_mvp_context()
        _mvp_print_dashboard(s,ledger)
        print('\n1  TAKE COURIER JOB')
        print('2  LOAD ACTIVE JOB CARGO')
        print('3  PLAN / FLY')
        print('4  UNLOAD + COMPLETE ACTIVE JOB')
        print('5  REFUEL REMASS')
        print('6  SERVICE / ADVANCE TIME')
        print('7  CAMPAIGN NOTE')
        print('8  STATUS + LLM HANDOFF')
        print('9  VERIFY SAVE + HISTORY')
        print('10 RECENT ACTIVITY')
        print('11 CANCEL UNLOADED JOB')
        print('12 ARCHIVE ACTIVE HISTORY')
        print('13 RECOVER / UNLOAD ACTIVE JOB')
        print('0  SAVE / EXIT')
        choice_raw=input('\nMVP ACTION: ')
        choice=choice_raw.strip().upper()
        cmd=_mvp_parse_menu_choice(choice_raw)
        try:
            if cmd=='1': _mvp_accept_interactive()
            elif cmd=='2': _mvp_load_interactive()
            elif cmd=='3': _mvp_flight_interactive()
            elif cmd=='4': _mvp_complete_interactive()
            elif cmd=='5': _mvp_refuel_interactive()
            elif cmd=='6': _mvp_service_interactive()
            elif cmd=='7': _mvp_note_interactive()
            elif cmd=='8':
                _,_,_,ss,ll=_mvp_context(); _mvp_print_dashboard(ss,ll); print('\\n'+_mvp_handoff(ss))
            elif cmd=='9': _mvp_verify()
            elif cmd=='10':
                _,_,_,ss,ll=_mvp_context(); _mvp_recent_activity(ll)
            elif cmd=='11': _mvp_cancel_interactive()
            elif cmd=='12': _mvp_archive()
            elif cmd=='13': _mvp_recover_interactive()
            elif cmd in ('0','Q','QUIT','EXIT'):
                print('CAMPAIGN SAVED          ',s['state_id'])
                return 0
            else:
                print('UNKNOWN ACTION')
        except Exception as e:
            print('\nACTION FAILED — NO UNCOMMITTED MVP STATE APPLIED')
            print(type(e).__name__+':',e)

def main():
    return _mvp_main()


